/* RepRival anatomical atlas overlays — grayscale figures are generated assets; heat zones are vector overlays. */
window.RepRivalBodyMap=(function(){
  const images={"front":"data:image/webp;base64,","back":"data:image/webp;base64,"};
  const regions={"front":{"Chest":["M155 265 Q180 246 234 249 Q268 250 301 268 Q306 308 295 336 Q286 359 257 367 Q212 373 179 344 Q153 329 155 265Z","M312 268 Q349 249 396 248 Q436 249 447 269 Q446 322 416 346 Q374 372 335 362 Q311 346 312 268Z"],"Back":[],"Side delts":["M139 230 Q110 231 104 260 Q94 302 113 340 Q123 353 144 351 Q160 325 165 291 Q170 254 139 230Z","M454 233 Q490 248 498 288 Q500 322 479 350 Q454 351 444 334 Q427 278 454 233Z"],"Rear delts":[],"Biceps":["M120 351 Q145 345 157 371 Q156 409 135 467 Q111 474 105 445 Q105 396 120 351Z","M457 350 Q477 344 487 365 Q505 405 500 443 Q493 467 474 464 Q449 425 457 350Z"],"Triceps":["M103 363 Q116 348 124 361 Q112 398 108 455 L90 485 Q91 410 103 363Z","M500 355 Q513 354 525 380 Q540 437 519 480 L502 449 Q505 399 500 355Z"],"Quads":["M200 683 Q231 674 263 687 Q278 734 274 800 Q275 873 248 912 Q220 940 195 914 Q173 869 181 786 Q182 714 200 683Z","M349 687 Q380 672 414 685 Q431 720 434 798 Q438 876 410 914 Q383 943 357 911 Q337 866 336 791 Q335 731 349 687Z"],"Hamstrings":[],"Glutes":[],"Calves":["M203 974 Q224 958 237 988 Q249 1055 231 1133 Q216 1169 201 1134 Q176 1043 203 974Z","M366 987 Q379 959 398 981 Q423 1040 402 1129 Q386 1170 374 1129 Q350 1045 366 987Z"],"Core":["M266 367 Q282 359 308 363 L307 641 Q285 679 267 637 Q246 548 255 437 Q254 384 266 367Z","M321 363 Q349 359 357 371 Q373 409 369 492 Q368 586 350 642 Q336 674 318 644Z"]},"back":{"Chest":[],"Back":["M159 223 Q198 217 277 200 L276 418 Q233 463 210 524 Q164 512 148 454 Q130 389 151 306Z","M295 201 Q343 217 406 224 Q425 287 428 365 Q431 467 364 525 Q342 466 294 419Z"],"Side delts":[],"Rear delts":["M139 246 Q109 255 93 290 Q88 320 107 339 Q132 354 155 342 Q176 304 162 270Z","M422 244 Q457 263 473 294 Q483 319 460 339 Q436 351 414 336 Q403 290 422 244Z"],"Biceps":[],"Triceps":["M107 348 Q129 345 146 366 Q149 423 121 480 Q94 464 89 421 Q90 377 107 348Z","M450 348 Q474 344 488 376 Q503 429 483 477 Q462 473 442 429 Q435 387 450 348Z"],"Quads":[],"Hamstrings":["M190 751 Q227 749 259 759 Q272 813 259 890 Q251 940 220 959 Q192 933 179 877 Q168 796 190 751Z","M320 751 Q361 746 397 763 Q410 811 403 879 Q390 936 368 960 Q336 939 321 888 Q307 810 320 751Z"],"Glutes":["M150 571 Q178 531 227 543 Q258 539 278 570 L278 694 Q260 732 227 740 Q171 732 145 686 Q134 630 150 571Z","M297 570 Q326 538 371 542 Q415 540 428 583 Q439 628 422 680 Q397 735 349 739 Q307 725 297 686Z"],"Calves":["M171 976 Q195 956 217 989 Q240 1030 220 1149 Q208 1191 185 1149 Q145 1060 171 976Z","M358 981 Q385 947 408 995 Q425 1060 407 1136 Q393 1182 376 1157 Q342 1071 358 981Z"],"Core":[]}};
  // Restore the detailed grayscale anatomical figure. Overlay strokes are in the
  // exact native image coordinate system (575/557 × 1402), and mask clipping
  // guarantees colour cannot bleed beyond the figure silhouette.
  function fillFor(p){
    const n=Math.max(0,Math.min(100,Number(p?.score??p??0)));
    const days=p?.last?Math.max(0,(Date.now()-Number(p.last))/86400000):0;
    if(p?.ever&&p?.historySets>=8&&p?.historySessions>=2&&days>=21&&n<12)return {fill:'#6d93db',alpha:.70};
    if(n<3)return {fill:'#ef4942',alpha:0};
    return {fill:n>=70?'#fd2b3c':'#e74846',alpha:Math.min(.82,.16+n/100*.68)};
  }
  function figure(side,scores={}){
    const width=side==='front'?575:557,paths=regions[side],id=side==='front'?'rr160Front':'rr160Back';
    const shapeList=Object.entries(paths).flatMap(([muscle,list])=>list.map((d,i)=>{
      const col=fillFor(scores[muscle]);/* Untrained regions remain transparent but tappable for detailed history. */
      // Both image and vector shapes share coordinates; the alpha mask clips the
      // zone fill strictly to visible anatomy instead of floating outside it.
      return `<path class="rr160-muscle-zone" data-muscle="${muscle}" tabindex="0" role="button" aria-label="${muscle}: view recent training" d="${d}" fill="${col.fill}" opacity="${col.alpha.toFixed(2)}" style="mix-blend-mode:multiply;pointer-events:visibleFill;filter:url(#rr161-soft-edge)"/>`;
    })).join('');
    return `<svg class="rr-figure-svg rr160-atlas" viewBox="0 0 ${width} 1402" role="group" aria-label="${side} anatomical muscle heatmap; select a muscle to view training details" xmlns="http://www.w3.org/2000/svg">
      <defs><filter id="rr161-soft-edge" x="-10%" y="-10%" width="120%" height="120%"><feGaussianBlur stdDeviation="3"/></filter><mask id="${id}-mask" maskUnits="userSpaceOnUse" maskContentUnits="userSpaceOnUse" x="0" y="0" width="${width}" height="1402" style="mask-type:alpha"><image x="0" y="0" width="${width}" height="1402" href="${images[side]}" preserveAspectRatio="none"/></mask></defs>
      <image x="0" y="0" width="${width}" height="1402" preserveAspectRatio="none" href="${images[side]}"/>
      <g mask="url(#${id}-mask)">${shapeList}</g>
    </svg>`;
  }
  return {figure};
})();
